css:
@keyframes spin { to { rotate: 360deg; } }
/* New item tint. Rows set --new-tint / --new-rest to tokens; keyframes stay token-free. */
@keyframes new-tint { 0%, 20% { background-color: var(--new-tint); animation-timing-function: cubic-bezier(0.37, 0, 0.63, 1); } 100% { background-color: var(--new-rest); } }
@keyframes new-tint-reduced { 0%, 91% { background-color: var(--new-tint); } 100% { background-color: var(--new-rest); } }
@keyframes new-tint-in { from { background-color: var(--new-rest); } to { background-color: var(--new-tint); } }
@keyframes new-tint-out { from { background-color: var(--new-tint); } to { background-color: var(--new-rest); } }

046mQbwY.css:
isolation: isolate;

&::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 50%;
  width: 36px;
  height: 36px;
  translate: -50% -50%;
  border-radius: 999px;
  background: color-mix(in srgb, {color.ink} 8%, transparent);
  z-index: -1;
  opacity: 0;
  scale: 0.7;
  transition:
    opacity 180ms ease-out,
    scale 180ms cubic-bezier(0.23, 1, 0.32, 1);
}

&:active::before {
  opacity: 1;
  scale: 1;
  transition-duration: 90ms;
}

04xJttpC.css:
transition:
  color 180ms ease-out,
  scale 250ms cubic-bezier(0.23, 1, 0.32, 1);

:active > & {
  color: {color.ink};
  scale: 0.9;
  transition-duration: 90ms, 250ms;
}

